// Builds prog.json (IR) for a Go file or package with the right overlay and
// tags, and validates it against src/ir/types.ts.
//
//   node scripts/frontend.ts <file.go | pkg dir> [-o out.json] [--config tests|tsgo|none]
//                            [-- extra frontend flags]
//
// Default output: .run/ir/<name>.json. Default config: tests (overlay/tests.json,
// regenerated by overlay/gen.ts). The front end binary is built into
// .run/frontend from frontend/ when its sources are newer.
import { execFileSync, spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readdirSync, readFileSync, statSync } from "node:fs";
import { basename, dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { validate } from "../src/ir/validate.ts";

const repo = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const frontendBin = join(repo, ".run", "frontend");

function newest(dir: string): number {
  let t = 0;
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    const s = statSync(p);
    t = Math.max(t, s.isDirectory() ? newest(p) : s.mtimeMs);
  }
  return t;
}

/** Builds .run/frontend if missing or older than frontend/**. */
export function buildFrontend(): string {
  if (!existsSync(frontendBin) || statSync(frontendBin).mtimeMs < newest(join(repo, "frontend"))) {
    mkdirSync(dirname(frontendBin), { recursive: true });
    execFileSync("go", ["build", "-o", frontendBin, "."], {
      cwd: join(repo, "frontend"),
      stdio: "inherit",
    });
  }
  return frontendBin;
}

/** The overlay JSON of a config (generated by overlay/gen.ts), or "" for none. */
export function overlayFor(config: string): string {
  if (config === "none") return "";
  const p = join(repo, "overlay", `${config}.json`);
  if (!existsSync(p)) execFileSync("node", [join(repo, "overlay", "gen.ts")], { stdio: "inherit" });
  return p;
}

export interface FrontendResult {
  out: string;
  log: string;
  errors: string[];
}

/** Runs the front end on a .go file or a package directory. */
export function runFrontend(
  target: string,
  out: string,
  config = "tests",
  extra: string[] = [],
): FrontendResult {
  const bin = buildFrontend();
  const abs = resolve(target);
  const isFile = abs.endsWith(".go");
  const dir = isFile ? dirname(abs) : abs;
  const args = ["-C", dir, "-o", out, ...extra];
  const ov = overlayFor(config);
  if (ov) args.push("-overlay", ov);
  args.push(isFile ? basename(abs) : ".");
  mkdirSync(dirname(out), { recursive: true });
  const r = spawnSync(bin, args, { encoding: "utf8", maxBuffer: 1 << 26 });
  const log = r.stdout + r.stderr;
  if (r.status !== 0) throw new Error(`frontend failed (${r.status}):\n${log}`);
  const prog: unknown = JSON.parse(readFileSync(out, "utf8"));
  return { out, log, errors: validate(prog) };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const argv = process.argv.slice(2);
  const dd = argv.indexOf("--");
  const extra = dd >= 0 ? argv.splice(dd).slice(1) : [];
  let out = "";
  let config = "tests";
  const rest: string[] = [];
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === "-o") out = argv[++i]!;
    else if (argv[i] === "--config") config = argv[++i]!;
    else rest.push(argv[i]!);
  }
  if (rest.length !== 1) {
    console.error(
      "usage: node scripts/frontend.ts <file.go | pkg dir> [-o out.json] [--config tests|tsgo|none] [-- flags]",
    );
    process.exit(2);
  }
  const target = rest[0]!;
  out ||= join(repo, ".run", "ir", basename(target).replace(/\.go$/, "") + ".json");
  try {
    const r = runFrontend(target, resolve(out), config, extra);
    process.stderr.write(r.log);
    const err = r.errors;
    if (err.length) {
      console.error(`invalid IR (${err.length} problems):\n${err.slice(0, 40).join("\n")}`);
      process.exit(1);
    }
    console.error(`valid: ${r.out}`);
  } catch (e) {
    console.error((e as Error).message);
    process.exit(1);
  }
}
